// 1. Data Source Configuration
datasource db {
  provider  = "postgresql"
  url       = env("DATABASE_URL")       // Direct or pooled connection
  directUrl = env("DIRECT_URL")         // Used for migrations in serverless setups
}

// 2. Client Code Generator
generator client {
  provider        = "prisma-client-js"
  previewFeatures = ["fullTextSearchPostgres", "metrics"]
}

// 3. Application Data Models
model Account {
  id           String    @id @default(cuid())
  name         String
  slug         String    @unique
  plan         PlanType  @default(FREE)
  createdAt    DateTime  @default(now())
  updatedAt    DateTime  @updatedAt
  users        User[]

  @@map("accounts") // Maps model to 'accounts' table in PostgreSQL
}

enum PlanType {
  FREE
  PRO
  ENTERPRISE
}
